type ApiErrorBody = {
  error?: {
    code?: string
    message?: string
    hint?: string
  }
}

/**
 * Removes sensitive data (connection strings and API keys) from an error message so it can be
 * safely surfaced to the user or logged.
 */
export function sanitizeErrorMessage(message: string): string {
  return message
    .replace(/(?:prisma\+)?postgres:\/\/[^\s'"]+/gi, '[REDACTED_URL]')
    .replace(/--api-key(?:=|\s+)\S+/gi, '--api-key [REDACTED]')
}

/**
 * Extracts a human-readable message from a Management API error body.
 */
function getApiErrorMessage(error: unknown, fallback: string): string {
  const body = error as ApiErrorBody | undefined
  return sanitizeErrorMessage(body?.error?.message ?? fallback)
}

/**
 * Maps a Management API error body to an `Error` with a user-facing message.
 */
function mapApiError(error: unknown): Error {
  const body = error as ApiErrorBody | undefined
  const code = body?.error?.code
  const message = body?.error?.message ?? 'Unknown error'

  if (code === 'authentication-failed') {
    return new Error('Invalid credentials. Please verify your API key and try again.')
  }
  if (code === 'not_found') {
    return new Error(`Database not found: ${sanitizeErrorMessage(message)}`)
  }
  return new Error(sanitizeErrorMessage(message))
}

/**
 * Creates a development connection string for the given database.
 *
 * Prefers the direct endpoint, falling back to the pooled endpoint, then to the deprecated
 * top-level `connectionString` field.
