/**
 * Status of the `.gitignore` file with respect to the `.env` entry.
 */
export type GitignoreStatus = 'no-file' | 'ok' | 'missing-entry'

/**
 * Metadata about which keys an `upsertEnvFile` call created, added, or updated.
 */
export interface UpsertEnvResult {
  created: boolean
  added: string[]
  updated: string[]
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Formats a single environment variable line. Values are wrapped in single quotes to prevent
 * variable expansion by shells and dotenv-style parsers.
 */
function formatEnvLine(key: string, value: string): string {
  return `${key}='${value}'`
}

/**
 * Creates or updates a `.env` file at `envPath` with the given key-value pairs.
 *
 * - If the file does not exist, it is created with all keys (returned `created` is `true`).
 * - If the file exists, existing keys are updated in-place and new keys are appended.
 *
 * Values are always written with single quotes in the form `KEY='value'\n`.
 */
export function upsertEnvFile(envPath: string, vars: Record<string, string>): UpsertEnvResult {
  const entries = Object.entries(vars)

  if (!existsSync(envPath)) {
    const content = entries.map(([key, value]) => `${formatEnvLine(key, value)}\n`).join('')
    writeFileSync(envPath, content)
    return { created: true, added: entries.map(([key]) => key), updated: [] }
  }

  const lines = readFileSync(envPath, 'utf8').split('\n')
  const added: string[] = []
  const updated: string[] = []

  for (const [key, value] of entries) {
    const regex = new RegExp(`^\\s*(?:export\\s+)?${escapeRegExp(key)}\\s*=`)
    const index = lines.findIndex((line) => regex.test(line))

    if (index === -1) {
      added.push(key)
    } else {
      lines[index] = formatEnvLine(key, value)
      updated.push(key)
    }
  }

  let content = lines.join('\n')

  if (added.length > 0) {
    if (content.length > 0 && !content.endsWith('\n')) {
      content += '\n'
    }
    content += added.map((key) => `${formatEnvLine(key, vars[key])}\n`).join('')
  }

  writeFileSync(envPath, content)
  return { created: false, added, updated }
}

/**
 * Checks whether a `.gitignore` file in `dir` exists and includes an entry for `.env`.
 */
export function checkGitignore(dir: string): GitignoreStatus {
  const gitignorePath = path.join(dir, '.gitignore')

  if (!existsSync(gitignorePath)) {
    return 'no-file'
  }

  const hasEnvEntry = readFileSync(gitignorePath, 'utf8')
    .split('\n')
    .some((line) => {
      const trimmed = line.trim()
      return trimmed === '.env' || trimmed === '/.env'
    })

  return hasEnvEntry ? 'ok' : 'missing-entry'
}

