function readDatabaseUrl(dir: string): string | undefined {
  const envPath = path.join(dir, '.env')
  if (!existsSync(envPath)) {
    return undefined
  }
  const parsed = dotenv.parse(readFileSync(envPath, 'utf8'))
  return parsed.DATABASE_URL
